import{_ as s,l as o,o as e,c as l,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"分布式文件与元数据","description":"","frontmatter":{"title":"分布式文件与元数据","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-fs-metadata.md","filePath":"cs/distributed-fs-metadata.md","lastUpdated":1789023840000}'),m={name:"cs/distributed-fs-metadata.md"};function h(S,a,E,_,A,u){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="分布式文件与元数据" tabindex="-1">分布式文件与元数据 <a class="header-anchor" href="#分布式文件与元数据" aria-label="Permalink to &quot;分布式文件与元数据&quot;">​</a></h1><div class="epigraph"><p>字节好分片，目录与 inode 难：一次 `rename` 要原子改两个目录。元数据服务的 QPS 与一致性往往先于数据面成为瓶颈。</p><footer>—— 据 GFS NameNode 经验；Weil et al., Ceph, OSDI 2006；POSIX rename 语义对照整理</footer></div><p>上一课<a href="/cs/object-storage-s3">对象存储</a>用扁平键避开目录原子。缺口是<strong>仍要文件系统 API</strong> 时：权限、目录、硬链接、rename。本课钉元数据面，不重写块流水线。后课 Borg 用到卷与隔离，不在本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HDFS NameNode 把树放内存，文件数墙。Ceph：动态子树或哈希到 MDS 集群，客户端缓存能力（capability），收回像<a href="/cs/leases">租约</a>。rename 跨 MDS 要分布式协议，类似短 2PC 或日志。缺口：数据三副本很便宜，元数据一次跨目录操作很贵。</p><p>POSIX：同一文件系统 rename 原子。分布式若只改一侧目录，崩溃则丢项或双项。这是<a href="/cs/consensus-vs-2pc">共识与 2PC</a>在 inode 上的投影。</p><p><span class="marginnote">Weil 的 Ceph 用 CRUSH 算数据位置，元数据另做 MDS。GFS 刻意弱 POSIX 就是为了躲这面墙。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分片键：按目录哈希则 rename 跨片；按子树则热目录热点。缓存：dentry 缓存必须能收回，否则权限撤销不可达。小文件：数据内联进元数据，避免每文件三副本开销。</p>',9)),(e(),d(c,null,{default:r(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NS%5B%22%E5%91%BD%E5%90%8D%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20MDS%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A%20%20MDS%20--%3E%20CAP%5B%22capability%20%2F%20%E7%A7%9F%E7%BA%A6%22%5D%0A%20%20IO%5B%22%E8%AF%BB%E5%86%99%22%5D%20--%3E%20OSD%5B%22%E5%AF%B9%E8%B1%A1%20%2F%20%E5%9D%97%22%5D%0A%20%20RN%5B%22rename%22%5D%20--%3E%20ATOM%5B%22%E8%B7%A8%E7%9B%AE%E5%BD%95%E5%8E%9F%E5%AD%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要让客户端只信本地 dentry 而不管收回。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与线性一致：打开文件后的读是否看到最新写，POSIX 与 NFS close-to-open 不同档。NFS 课已有语义，本课只提醒分布式集群同样要声明。与对象：没有 rename 原子时，应用用「写临时键 + 条件换键」模拟，失败窗口自己管。</p><p>本课不写 POSIX 每一条。也不写光电刻蚀。</p><p>热父目录（所有人 mkdir 同一文件夹）是元数据热键，接<a href="/cs/cache-stampede-hotkey">热键</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Lustre 全部协议写完。后课默认：选对象还是选文件系统，先问是否要跨目录原子与 POSIX。Borg/k8s 下一课消费这两种存储当卷。Tail at Scale 再谈元数据 RPC 的尾延迟。</p><p>数据面扩展不等于 API 扩展。目录是共享可变对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>元数据 rename/mkdir 是分布式原子问题。</li><li>NameNode 单树内存是墙；MDS 分片有热目录与跨片税。</li><li>capability 收回同租约；客户端缓存必须能失效。</li><li>出处：GFS；Weil et al., OSDI 2006。</li></ul>',10))])}const P=s(m,[["render",h]]);export{f as __pageData,P as default};
